def write() -> None:
    rows = [{c: s.get(c, "") for c in COLUMNS} for s in P0_SOURCES] + [{c: s.get(c, "") for c in COLUMNS} for s in P1B]
    with open(OUT, "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=COLUMNS)
        w.writeheader()
        w.writerows(rows)
    print(f"{len(rows)} sources written to {OUT}")


if __name__ == "__main__":
    write()
